#!/usr/bin/env bash
set -Eeuo pipefail
umask 027
[[ "$EUID" -eq 0 ]] || { echo "Run as root" >&2; exit 1; }
venv=/opt/auto-photo-ingest/venv
work_dir="$(mktemp -d /root/auto-photo-v03.XXXXXX)"
cleanup() { rm -rf -- "$work_dir"; }
trap cleanup EXIT
systemctl stop auto-photo-ingest.timer
for _ in {1..60}; do systemctl is-active --quiet auto-photo-ingest.service || break; sleep 1; done
systemctl is-active --quiet auto-photo-ingest.service && { echo "Worker is still active" >&2; exit 1; }
cat > "$work_dir/package.whl.b64" <<'PAYLOAD'

PAYLOAD
base64 -d "$work_dir/package.whl.b64" > "$work_dir/auto_photo_ingest-0.3.0-py3-none-any.whl"
printf '%s  %s
' '19ec39e924c4861a8aeda44530844693bbd12e06773f7bd312de676152b15921' "$work_dir/auto_photo_ingest-0.3.0-py3-none-any.whl" | sha256sum -c -
$venv/bin/python -m pip install --no-deps --force-reinstall "$work_dir/auto_photo_ingest-0.3.0-py3-none-any.whl"
chmod -R a+rX "$venv"
$venv/bin/python -c "import auto_photo_ingest.cli, auto_photo_ingest.vision; print('IMPORTS=OK')"
$venv/bin/python - <<'PY2'
from pathlib import Path
unit=Path('/etc/systemd/system/auto-photo-ingest.service')
text=unit.read_text()
line='EnvironmentFile=-/etc/auto-photo-ingest/openai.env
'
if line not in text:
    anchor='Environment=PYTHONUNBUFFERED=1
'
    if anchor not in text:
        raise SystemExit('Service unit anchor missing')
    unit.write_text(text.replace(anchor, anchor+line))
PY2
systemctl daemon-reload
runuser -u auto-photo-ingest -- "$venv/bin/auto-photo-ingest" init --data-dir /var/lib/auto-photo-ingest
runuser -u auto-photo-ingest -- "$venv/bin/auto-photo-ingest" screen-export --data-dir /var/lib/auto-photo-ingest --output-dir /var/lib/auto-photo-ingest/screening
systemctl reset-failed auto-photo-ingest.service 2>/dev/null || true
systemctl start auto-photo-ingest.service
systemctl enable --now auto-photo-ingest.timer
printf 'UPGRADE=OK
VERSION='
$venv/bin/python -c "from importlib.metadata import version; print(version('auto-photo-ingest'))"
printf 'PENDING_MODEL='
$venv/bin/python - <<'PY3'
import sqlite3
c=sqlite3.connect('/var/lib/auto-photo-ingest/catalogue.sqlite3')
print(c.execute("select count(*) from vehicle_candidates where decision='pending_model'").fetchone()[0])
PY3
printf 'TIMER='
systemctl is-active auto-photo-ingest.timer
